  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Creates a new IPO application for this retail customer.
   * The customer must provide the target company, a share count greater than 0, a payment amount greater than 0,
   * and a non-null allowance document.
   * The system prevents duplicate approved applications for the same company and checks IPO eligibility before creation.
   * Algorithm:
   * 1. Validate that company is not null.
   * 2. Validate that shares > 0.
   * 3. Validate that amount > 0.
   * 4. Validate that doc is not null and doc.name is not null/empty.
   * 5. Check isEligibleForIPO() == true.
   * 6. Check there is no existing APPROVAL application for the same company.name.
   * 7. If any check fails, return false.
   * 8. Create a new Application with:
   *    - company
   *    - customer = this
   *    - share = shares
   *    - amountOfMoney = amount
   *    - allowance = doc
   *    - status = PENDING
   * 9. Add the application to applications.
   * 10. Return true.
   * Related Features:
   * - applications
   * - canApplyForIPO
   * - isEligibleForIPO()
   * Related Classes: Application, Company, Document, ApplicationStatus
   * Input:
   * - company : Company
   *   - Target company for the IPO application.
   * - shares : int
   *   - Number of shares to apply for; must be > 0.
   * - amount : double
   *   - Amount of money to be paid; must be > 0.
   * - doc : Document
   *   - Legal allowance document; must be non-null and should have a valid name.
   * Output:
   * - boolean: true if the application record is created successfully, otherwise false.
   * Pre-condition:
   * - The customer exists and is a retail customer eligible for IPO.
   * - The provided company, shares, amount, and document satisfy validation rules.
   * - No approved application already exists for the same company name.
   * Post-condition:
   * - If successful, a new pending application is added to applications.
   * - The new application references the provided company, this customer, the allowance document, share count, and amount.
   * - If unsuccessful, no new application is added.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean createApplication(final Company company, final int shares, final double amount, final Document doc)
  {
    if (company == null || shares <= 0 || amount <= 0)
    {
      return false;
    }
    if (doc == null || doc.getName() == null || doc.getName().trim().isEmpty())
    {
      return false;
    }
    if (!isEligibleForIPO())
    {
      return false;
    }
    String companyName = company.getName();
    if (companyName == null || companyName.trim().isEmpty())
    {
      return false;
    }
    for (Application application : getApplications())
    {
      if (application != null && application.getCompany() != null && companyName.equals(application.getCompany().getName())
          && application.getStatus() == ApplicationStatus.APPROVAL)
      {
        return false;
      }
    }
    Application application = IpoFactory.eINSTANCE.createApplication();
    application.setCompany(company);
    application.setCustomer(this);
    application.setShare(shares);
    application.setAmountOfMoney(amount);
    application.setAllowance(doc);
    application.setStatus(ApplicationStatus.PENDING);
    getApplications().add(application);
    return true;
  }

